window.BIZ_PAPERS = (window.BIZ_PAPERS || []).concat([{"id": "HSC2-SAM", "unit": 2, "key": "SAM", "series": "Sample assessment (AAQ)", "date": "Pearson sample assessment material", "title": "Pearson sample paper", "source": "pearson", "kind": "exam", "code": "Sample", "spec": "new", "total": 80, "minutes": 90, "items": [{"q": 1, "sub": "a", "marks": 1, "section": "A", "ctx": [], "text": "Identify one type of epithelial tissue.\nA  Bone\nB  Simple\nC  Nervous\nD  Striated", "ms": {"body": "Award one mark for the following:\nB\nSimple", "levels": null}}, {"q": 1, "sub": "b", "marks": 3, "section": "A", "ctx": ["Figure 1 shows a diagram of the human respiratory system. A B C"], "text": "Label structures A, B and C on Figure 1.", "ms": {"body": "Award one mark for each of the following up to\na maximum of three marks\n• A - trachea\n• B – rib(s)\n• C - lung", "levels": null}}, {"q": 1, "sub": "c", "marks": 2, "section": "A", "ctx": [], "text": "State the names of two cell organelles.", "ms": {"body": "Award one mark for each of the following up to\na maximum of two marks:\n• Membrane\n• Nucleus\n• Ribosomes\n• Mitochondria\nAccept any other appropriate response.", "levels": null}}, {"q": 1, "sub": "d", "marks": 3, "section": "A", "ctx": [], "text": "Describe how oxygen passes from the lungs into the bloodstream.", "ms": {"body": "Award one mark for each appropriate point in a\nlinked description up to a maximum of three\nmarks.\n• high levels of oxygen in the alveoli (1)\nand low levels of oxygen in the\nbloodstream (1) lead to a diffusion\ngradient across the membrane/from\nalveoli to the blood/capillaries (1)\nAccept any other appropriate wording/phrasing.", "levels": null}}, {"q": 1, "sub": "e", "marks": 4, "section": "A", "ctx": [], "text": "Explain the role of the diaphragm and the intercostal muscles in ventilation.", "ms": {"body": "Award one mark for the identification of the role\nof the diaphragm and one mark for an\nappropriate linked expansion, up to a maximum\nof two marks.\nDiaphragm\n• During inspiration, the diaphragm\ncontracts and moves down (1) which\nincreases the volume/decreases the\npressure of the lungs (1)\n• During expiration, the diaphragm relaxes\nand moves up (1) which decreases the\nvolume/increases the pressure of the\nlungs (1)\nAward one mark for the identification of the role\nof the intercostal muscles and one mark for an\nappropriate linked expansion, up to a maximum\nof two marks.\nIntercostal muscles\n• During inspiration, the intercostal\nmuscles contract pulling the ribs up (1)\nwhich increases the volume/decreases\nthe pressure in the lungs (1)\n• During expiration, the intercostal muscles\nrelax allowing the ribs to return to resting\n(1) which decreases the\nvolume/increases the pressure in the\nlungs (1)\nAccept any other appropriate wording/phrasing.", "levels": null}}, {"q": 1, "sub": "f", "marks": 4, "section": "A", "ctx": ["Diaphragm Intercostal muscles"], "text": "Explain two ways red blood cells are adapted to deliver oxygen.", "ms": {"body": "Award one mark for each identification of a way\nand one mark for an appropriate linked\nexpansion of each, up to a maximum of four\nmarks.\n• Provides increased rate of oxygen\ndiffusion (1) because they have a large\nsurface area/concave shape/thin\nmembrane (1)\n• Has more oxygen carrying capacity (1)\nbecause they don’t have a nucleus (1)\n• Oxygen binds effectively to the cells (1)\nbecause they contain haemoglobin (1)\nAccept any other appropriate responses.", "levels": null}}, {"q": 1, "sub": "g", "marks": 9, "section": "A", "ctx": ["Charlie is 16. They have just completed a cross-country run and are struggling to breathe. Charlie’s lips are blue, and they are slightly confused. They are having an asthma attack."], "text": "Discuss how an asthma attack can affect Charlie’s cardiovascular and central\nnervous systems.", "ms": {"body": "Learners might refer to some/all of the following in their responses,\nbut learners should be rewarded for other pertinent contextualised\nanswers:\n• Asthma is the narrowing of the trachea/bronchi, due to\ninflammation.\n• This limits oxygen in/carbon dioxide out.\n• In the case of an asthma attack this leads to breathlessness and\nincreased breathing rate as the body struggles to get oxygen in.\nCardiovascular\n• The increased demand for oxygen and increased carbon dioxide\nlevels in the blood causes the heart rate to increase. The reduced\noxygen in the blood can affect the brain functioning in the short\nterm as oxygen is not available for respiration so no energy\navailable.\n• Unoxygenated blood in the arteries causes blue lips and fingers.\nCentral nervous system\n• Reduced oxygen in the blood impairs cellular respiration, reducing\nenergy available, affecting brain function in the short term.\n• Confusion and dizziness as the brain runs out of oxygen, leading to\ndrowsiness and eventually fainting.\n• Longer term effects can cause anxiety and depression which are\neffects on the brain.\nMark scheme (award up to 9 marks) refer to specific marking guidance earlier\nin this document for more detail.\nLevel\nDescriptor\nLevel 0\n0\nNo rewardable material.\nLevel 1\n1–3\n• Limited discussion which contains generic assertions rather\nthan considering different aspects and the relationship\nbetween them. (AO4)\n• Demonstrates basic application of knowledge and\nunderstanding that is partially relevant to the context of\nthe question and may consider only one side of the context\n(AO3)\nLevel 2\n4–6\n• Displays a partially developed discussion which considers\nsome different aspects and some consideration of how they\ninterrelate, but not always in a sustained way. (AO4)\n• Demonstrates good application of knowledge and\nunderstanding that is relevant to the context of the\nquestion and considers both sides of the context. (AO3)\nLevel 3\n7–9\n• Displays a well-developed and logical discussion which\nclearly considers a range of different aspects and considers\nhow they interrelate, in a sustained way. (AO4)\n• Demonstrates comprehensive application of knowledge and\nunderstanding that is consistently relevant to the context\nof the question and considers both sides of the context in a\nbalanced way. (AO3)\nSection B", "levels": null}}, {"q": 2, "sub": "a", "marks": 1, "section": "B", "ctx": [], "text": "Identify one type of muscle tissue.\nA  Adipose\nB  Cartilage\nC  Cardiac\nD  Neuroglia", "ms": {"body": "C\nCardiac", "levels": null}}, {"q": 2, "sub": "b", "marks": 2, "section": "B", "ctx": ["Figure 2 shows a diagram of the digestive system. A B"], "text": "Label structures A and B on Figure 2.", "ms": {"body": "Award one mark for each of the following up to\na maximum of two marks\n• A – stomach\n• B - gallbladder", "levels": null}}, {"q": 2, "sub": "c", "marks": 3, "section": "B", "ctx": [], "text": "Describe the route that food takes from the mouth to the colon.", "ms": {"body": "Award one mark for each appropriate point in a\nlinked description up to a maximum of three\nmarks.\n• Down the oesophagus (1) then through\nthe stomach (1) then through the small\nintestine (accept individually named\nparts) (1)\nAccept any other appropriate wording/phrasing.", "levels": null}}, {"q": 2, "sub": "d", "marks": 4, "section": "B", "ctx": [], "text": "Explain two roles of the salivary glands in the breakdown of food.", "ms": {"body": "Award one mark for each identification of a role\nand one mark for an appropriate linked\nexpansion of each up to a maximum of four\nmarks.\n• Produces amylase (1) to break down\nstarch (1)\n• Produce lipases (1) to start fat digestion\n• Moistens food (1) to ease swallowing/aid\nchewing (1)\nAccept any other appropriate response.", "levels": null}}, {"q": 2, "sub": "e", "marks": 4, "section": "B", "ctx": [], "text": "Explain the role of the liver and pancreas in regulating blood sugar levels.", "ms": {"body": "Award one mark for the identification of the role\nof the liver and one mark for an appropriate\nlinked expansion, up to a maximum of two\nmarks.\nLiver\n• stores (free/blood) glucose as glycogen\n(1) so that it can be released when\nrequired to increase blood sugar levels\nAward one mark for the identification of the role\nof the pancreas and one mark for an\nappropriate linked expansion, up to a maximum\nof two marks.\nPancreas\n• produces glucagon when blood sugar is\nlow (1) which increases blood sugar\nlevels. (1)\n• produce insulin when blood sugar is high\n(1) which reduces glucose levels in the\nblood (1)\nAccept any other appropriate wording/phrasing.", "levels": null}}, {"q": 2, "sub": "f", "marks": 3, "section": "B", "ctx": ["Liver Pancreas"], "text": "Explain one way the endocrine system controls growth.", "ms": {"body": "Award one mark for identification of a way, one\nmark for an appropriate linked expansion and\none mark for a further expansion, up to a\nmaximum of three marks.\n• The thyroid gland produces growth\nstimulating hormone (1) which stimulates\nbone-forming cells/which stimulates bone\ngrowth (1) which increases height/size\n• The ovaries produce oestrogen/the testes\nproduce testosterone (1) which matures\nsexual characteristics (1) so reproduction\ncan occur (1)\nAccept any other appropriate responses.", "levels": null}}, {"q": 2, "sub": "g", "marks": 3, "section": "B", "ctx": [], "text": "Explain one way the combination of genetics and lifestyle can cause bowel\ncancer.", "ms": {"body": "Award one mark for identification of a way, one\nmark for an appropriate linked expansion and one\nmark for a further expansion, up to a maximum of\nthree marks.\n• Genetic predisposition to cancer (1)\ncombined with smoking/consumption of red\nand processed meat/alcohol consumption\n(1) this carcinogen may lead to\nuncontrolled cell growth (cancer) (1)\n• Cancer risk genes (1) combined with being\noverweight and obese (1) extra fat in the\nbody signals the cells in the body to divide\nmore often which can lead to cancer (1)\nAccept any other valid response.", "levels": null}}, {"q": 2, "sub": "h", "marks": 9, "section": "B", "ctx": ["Alex is a 52-year-old with a bowel cancer diagnosis; they are now experiencing pain, fatigue and weight loss."], "text": "Discuss the ways in which the effects of bowel cancer on the digestive system\nhave an impact on Alex’s other body systems.", "ms": {"body": "Learners might refer to some/all of the following in their\nresponses, but learners should be rewarded for other pertinent\ncontextualised answers:\n• The main effects on the digestive system are changes in\nfaeces, changes in occurrence of defaecating, bleeding from\nthe anus/blood in stool, pain in the abdomen, bloating, due to\nthe tumour damaging and blocking the intestine.\n• The diversion of nutrients to the tumour can affect the\nmusculoskeletal system as muscle mass is lost, leading to\nweight loss.\n• Persistent bleeding can cause anaemia in the circulatory\nsystem, leading to lethargy and breathlessness.\n• Advanced or secondary bowel cancer happens when it\nmetastasises, commonly to the liver, lungs or peritoneum.\nLeads to organ failure and is often fatal.\nMark scheme (award up to 9 marks) refer to specific marking guidance earlier\nin this document for more detail.\nLevel\nDescriptor\nLevel 0\nNo rewardable material.\nLevel 1\n1–3\nLevel 2\n4–6\nLevel 3\n7–9\n22\nSection C", "levels": null}}, {"q": 3, "sub": "a", "marks": 1, "section": "C", "ctx": [], "text": "Identify one location of nervous tissue in the body.\nA  Brain\nB  Ovaries\nC  Ligaments\nD  Alveoli", "ms": {"body": "Award one mark for the following:\nA\nBrain", "levels": null}}, {"q": 3, "sub": "b(i)", "marks": 1, "section": "C", "ctx": [], "text": "State one type of neurone.", "ms": {"body": "Award one mark for one of the following:\n• sensory\n• motor\n• relay\nAccept any other appropriate response.", "levels": null}}, {"q": 3, "sub": "b(ii)", "marks": 2, "section": "C", "ctx": [], "text": "State two roles of the central nervous system.", "ms": {"body": "Award one mark for each of the following up to\na maximum of two marks:\n• receiving information (1)\n• processing information (1)\n• coordinating information (1)\n• transmitting information (1)\nAccept any other appropriate wording.", "levels": null}}, {"q": 3, "sub": "c", "marks": 4, "section": "C", "ctx": [], "text": "Explain the role of parasympathetic and sympathetic nervous systems in\nregulating heart rate.", "ms": {"body": "Award one mark for the identification of the role\nof the parasympathetic nervous system and one\nmark for an appropriate linked expansion, up to\na maximum of two marks.\nParasympathetic\n• To reduce the heart rate back to resting\nlevels (1) when the heart rate is\nhigh/carbon dioxide levels is low (1)\nAward one mark for the identification of the role\nof the sympathetic nervous system and one\nmark for an appropriate linked expansion, up to\na maximum of two marks.\nSympathetic\n• It increases heart rate to increase oxygen\nsupply to the muscles (1) when oxygen\ndemand increases/carbon dioxide levels\nincrease (1)\nAccept any other appropriate wording/phrasing.", "levels": null}}, {"q": 3, "sub": "d", "marks": 2, "section": "C", "ctx": ["Parasympathetic Sympathetic"], "text": "Explain one way that negative feedback mechanisms will maintain body\ntemperature.", "ms": {"body": "Award one mark for identification of a way and\none mark for an appropriate linked expansion, up\nto a maximum of two marks.\n• causes sweating/vasodilation (1) to cause\ntemperature reduction/increase heat loss\n(1)\n• causes shivering/vasoconstriction (1) to\nincrease temperature/decrease heat loss\nAccept any other appropriate wording/phrasing.", "levels": null}}, {"q": 3, "sub": "e", "marks": 3, "section": "C", "ctx": [], "text": "Explain the role of the peripheral nervous system in controlling movement.", "ms": {"body": "Award one mark for identification of a role, one\nmark for an appropriate linked expansion and\none mark for a further expansion, up to a\nmaximum of three marks.\n• it relays information to the muscles from\nthe central nervous system/down the\nmotor neurones (1) which causes muscles\nto contract (1) enabling movement of the\nskeleton (1)\nAccept any other appropriate wording/phrasing.", "levels": null}}, {"q": 3, "sub": "f", "marks": 3, "section": "C", "ctx": [], "text": "Explain one role of adrenaline in the fight or flight response.", "ms": {"body": "Award one mark for identification of a role, one\nmark for an appropriate linked expansion and\none mark for a further expansion, up to a\nmaximum of three marks.\n• to prepare the body for action (1) by\nincreasing metabolism/heart\nrate/breathing rate (1) to increase the\nenergy supply (1)\n• to prepare the body for action (1) by\ndilating the pupils (1) to improve\ninformation reception (1)\n• to prepare the body for action (1) by\nincreasing the blood supply to the brain\n(1) to increase processing speed/cognitive\nfunctioning (1)\nAccept any other appropriate responses.", "levels": null}}, {"q": 3, "sub": "g", "marks": 9, "section": "C", "ctx": ["Ali had a cycling accident and sustained a traumatic brain injury. They are currently having physiotherapy and speech and language therapy as part of their rehabilitation."], "text": "Discuss how Ali’s traumatic brain injury may affect the functioning of the central\nnervous system and other body systems.", "ms": {"body": "Learners might refer to some/all of the following in their responses, but\nlearners should be rewarded for other pertinent contextualised answers:\n• Movement/mobility problems – coordination of muscles for movement or\nmobility and for speech and swallowing\n• Control of bladder and bowels – nervous system\nCognitive and communication\n• Aphasia/dysphasia when the speech centres are affected.\n• Forming clear words when the motor function is affected.\n• Memory can be impaired.\n• There can be changes in sensory perception, e.g. taste sensations can\nchange.\nPhysical\n• Fatigue is a common effect.\n• Mobility issues if the messages from the brain are not reaching the\nmuscles, or the brain cannot coordinate information to elicit a response.\n• The messages to and from the bladder and/or bowels can lead to\nincontinence.\n• Swallowing becomes difficult if the throat muscles are not coordinated.\nBehavioural and emotional\n• The ability to control or feel emotions is affected. There can be changes\nin behaviour.\nMark scheme (award up to 9 marks) refer to specific marking guidance earlier in this\ndocument for more detail.\nLevel\nMark Descriptor\nLevel 0\nNo rewardable material.\nLevel 1\n1–3\n• Limited discussion which contains generic assertions rather than\nconsidering different aspects and the relationship between them.\n• Demonstrates basic application of knowledge and understanding\nthat is partially relevant to the context of the question and may\nconsider only one side of the context.\nLevel 2\n4–6\n• Displays a partially developed discussion which considers some\ndifferent aspects and some consideration of how they interrelate,\nbut not always in a sustained way.\n• Demonstrates good application of knowledge and understanding\nthat is relevant to the context of the question and considers both\nsides of the context.\nLevel 3\n7–9\n• Displays a well-developed and logical discussion which clearly\nconsiders a range of different aspects and considers how they\ninterrelate, in a sustained way.\n• Demonstrates comprehensive application of knowledge and\nunderstanding that is consistently relevant to the context of the\nquestion and considers both sides of the context in a balanced\nway.\n25\nJuly 2024\nFor information about Pearson Qualifications, including Pearson Edexcel\nand BTEC qualifications visit qualifications.pearson.com\nEdexcel and BTEC are registered trademarks of Pearson Education Limited\nPearson Education Limited. Registered in England and Wales No. 872828\nRegistered Office: 80 Strand, London WC2R 0RL.\nVAT Reg No GB 278 537121\nBTEC", "levels": null}}], "badge": "Pearson · current spec", "badgeTone": "new", "notice": "Pearson’s sample assessment for the current AAQ specification: the closest match to the real exam. Figures, tables and information booklets are described in words."}]);
